public class E211 {
    static class P {
        int x;
        P(int x){ this.x = x; }
        @Override public boolean equals(Object o){ return o instanceof P p && x == p.x; }
    }
    public static void main(String[] args) {
        P a = new P(1);
        P b = new P(1);
        System.out.println("a==b: " + (a == b));
        System.out.println("a.equals(b): " + a.equals(b));
        P c = a;
        System.out.println("a==c: " + (a == c));
    }
}
